const { Duration } = require("/luxon/src/luxon.js");

const units = [
  "years",
  "quarters",
  "months",
  "weeks",
  "days",
  "hours",
  "minutes",
  "seconds",
  "milliseconds"
];

function close(a, b) {
  if (!isFinite(a) || !isFinite(b)) return false;
  if (a === b) return true;
  const diff = Math.abs(a - b);
  const scale = Math.max(Math.abs(a), Math.abs(b));
  return diff / scale <= 1e-9;
}

function runLoop(label, opts) {
  let failures = 0;
  for (const a of units) {
    for (const b of units) {
      const orig = Duration.fromObject({ [a]: 1, [b]: 1 }, opts);
      const norm = orig.normalize();
      const got = norm.as("milliseconds");
      const expected = orig.as("milliseconds");
      if (!norm.isValid || !isFinite(got) || !close(got, expected)) {
        failures++;
        console.log(
          `FAIL [${label}] ${a}/${b}: valid=${norm.isValid} got=${got} expected=${expected} obj=${JSON.stringify(
            norm.toObject()
          )}`
        );
      }
    }
  }
  console.log(`TOTAL FAILURES [${label}]: ${failures}`);
  return failures;
}

