const { objToLocalTS } = require("/luxon/src/impl/util.js");

function oldObjToLocalTS(obj) {
  let d = Date.UTC(
    obj.year,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  if (obj.year < 100 && obj.year >= 0) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 1900);
  }
  return +d;
}

function ref(obj) {
  const d = new Date(
    Date.UTC(obj.year + 4000, obj.month - 1, obj.day, obj.hour, obj.minute, obj.second, obj.millisecond)
  );
  d.setUTCFullYear(d.getUTCFullYear() - 4000);
  return +d;
}

const years = [0, 1, 4, 96, 99, 100];
const days = [-2, -1, 0, 1, 28, 29, 30, 31, 32, 60, 90, 91, 92, 120];

function run(fn, name) {
  let mismatches = 0;
  for (const year of years) {
    for (let month = 1; month <= 12; month++) {
      for (const day of days) {
        const obj = { year, month, day, hour: 0, minute: 0, second: 0, millisecond: 0 };
        const got = fn(obj);
        const expected = ref(obj);
        if (got !== expected) {
          mismatches++;
          console.log(
            `MISMATCH[${name}] year=${year} month=${month} day=${day} got=${got} (${new Date(got).toISOString()}) expected=${expected} (${new Date(expected).toISOString()})`
          );
        }
      }
    }
  }
  console.log(`TOTAL MISMATCHES [${name}]: ${mismatches}`);
  return mismatches;
}

run(oldObjToLocalTS, "old");
run(objToLocalTS, "current");
